import "dart:convert"; import "package:http/http.dart" as http; import "lib/models/course_model.dart"; void main() async { try { final url = Uri.parse("https://coders-adda-backend.onrender.com/lecture/get/by-topic/6a6db9805fed19b56a7f4d55"); final response = await http.get(url); final decoded = jsonDecode(response.body); if (decoded["success"] == true) { final List<dynamic> data = decoded["data"]; final lectures = data.map((item) => CourseLecture.fromJson(item)).toList(); print("Lectures count: ${lectures.length}"); } else { print("Success is false"); } } catch (e, stack) { print("Error: $e"); print(stack); } }
